/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.util.List;
import java.util.Set;

import net.civeira.phylax.feature.observe.metric.MetricPoint;

/**
 * Where the logs and spans are kept. The configuration, the origins and the rest of the entities
 * are always in the database; this store only keeps the high volume data.
 */
public interface TelemetryStore {

  void appendLogs(List<ObsLog> logs);

  void appendSpans(List<ObsSpan> spans);

  /** Logs of the query, newest first. */
  List<ObsLog> logs(TelemetryQuery query);

  /** Spans of the query, newest first. */
  List<ObsSpan> spans(TelemetryQuery query);

  /** Every span of a trace, in start order. */
  List<ObsSpan> trace(String traceId, long from, long to);

  /** Every span of the given traces (one read of the range), in start order. */
  List<ObsSpan> traces(Set<String> traceIds, long from, long to);

  /** Metric points of one minute or one hour ({@link MetricPoint#step}). */
  void appendPoints(List<MetricPoint> points);

  /**
   * Metric points of the range, oldest first.
   *
   * @param step 60 000 (minutes) or 3 600 000 (hours)
   * @param sources codes of the sources; empty for all
   */
  List<MetricPoint> points(long from, long to, long step, Set<String> sources);

  /** Bytes the store takes on disk (it may be a few minutes old). */
  long sizeBytes();

  /** Deletes the data older than the retention and, above the disk limit, the oldest days. */
  void purge(RetentionPolicy policy);

  /**
   * Applies the disk limit of the policy now (called every few minutes, the purge is daily): above
   * it the oldest data is deleted and, if nothing else can go, the store rejects new events.
   */
  default void enforce(final RetentionPolicy policy) {}

  /**
   * Every few minutes: deletes the logs and spans older than the hours of the level of their trace
   * ({@link RetentionPolicy#levels}). Nothing if the policy has no retention by level.
   */
  default void purgeLevels(final RetentionPolicy policy) {}

  /** Whether the store is at its disk limit and rejects new events. */
  default boolean full() {
    return false;
  }

  /** Events rejected because the store was full, since the start. */
  default long rejected() {
    return 0;
  }
}
